1	"use client";
2	
3	/**
4	 * GameShowcaseCarousel — a premium, horizontally-scrolling showcase of the
5	 * supported game titles for the marketing /game-servers hero. Each title is a
6	 * "cover" card built from the owner's real <GameLogo> mark on its per-game brand
7	 * gradient, with a soft brand-colour glow. The active card expands to reveal an
8	 * interactive player-slot selector whose pills + "Starting at $X/mo" are driven
9	 * ENTIRELY by the DB game-plan tiers passed in (no invented player counts or
10	 * prices). Reduced-motion users get the resting frame — every transition is
11	 * motion-safe.
12	 *
13	 * Interaction:
14	 *   • Click any cover (or use the ◀ ▶ arrows) to make it the active title.
15	 *   • The active title shows "Players" pills, one per DB tier that defines
16	 *     `slots`; picking a pill swaps the shown price + RAM to that exact tier.
17	 *   • Mobile: the track is a CSS scroll-snap carousel (swipe horizontally).
18	 */
19	
20	import { useRef, useState } from "react";
21	import Link from "next/link";
22	import { GameLogo, GAME_VISUAL } from "../GameLogo";
23	import { IconArrow, IconUsers, IconBolt } from "../icons";
24	
25	/** One DB-fed price tier for a game (subset of db.gamePlan). */
26	export type ShowcaseTier = {
27	  name: string;
28	  ramMB: number;
29	  cpuCores: number;
30	  diskGB: number;
31	  slots: number | null;
32	  priceCents: number;
33	  termMonths: number;
34	  featured: boolean;
35	};
36	
37	/** One game title in the showcase (built server-side from db.gamePlan). */
38	export type ShowcaseGame = {
39	  family: string;
40	  name: string;
41	  tag: string;
42	  /** Cheapest active tier for this title, in cents. DB-derived. */
43	  fromCents: number;
44	  tiers: ShowcaseTier[];
45	};
46	
47	function money(cents: number) {
48	  const v = cents / 100;
49	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
50	}
51	function gb(mb: number) {
52	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
53	}
54	function per(term: number) {
55	  return term > 1 ? `/ ${term} mo` : "/mo";
56	}
57	
58	const NEUTRAL = { from: "#334155", to: "#64748b" };
59	
60	function ActivePanel({ game }: { game: ShowcaseGame }) {
61	  // Tiers that define player slots power the interactive selector. Fall back to
62	  // the raw tier order when a title has no slotted tiers (still DB-fed).
63	  const slotted = game.tiers.filter((t) => t.slots != null);
64	  const options = slotted.length ? slotted : game.tiers;
65	  // Default selection = the featured tier if present, else the cheapest.
66	  const defaultIdx = Math.max(
67	    0,
68	    options.findIndex((t) => t.featured),
69	  );
70	  const [sel, setSel] = useState(defaultIdx === -1 ? 0 : defaultIdx);
71	  const tier = options[sel] ?? game.tiers[0];
72	
73	  if (!tier) return null;
74	
75	  return (
76	    <div className="mt-4 border-t border-white/[0.07] pt-4">
77	      {slotted.length > 0 && (
78	        <>
79	          <p className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400">
80	            <IconUsers size={13} /> Player slots
81	          </p>
82	          <div className="mt-2 flex flex-wrap gap-1.5" role="group" aria-label={`${game.name} player slots`}>
83	            {options.map((t, i) => (
84	              <button
85	                key={`${t.name}-${i}`}
86	                type="button"
87	                aria-pressed={i === sel}
88	                onClick={() => setSel(i)}
89	                className={`rounded-lg border px-2.5 py-1 text-xs font-semibold transition-colors ${
90	                  i === sel
91	                    ? "border-brand-400/60 bg-brand-500/15 text-white"
92	                    : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:text-white"
93	                }`}
94	              >
95	                {t.slots}
96	              </button>
97	            ))}
98	          </div>
99	        </>
100	      )}
101	
102	      {/* Selected-tier detail — every figure below is straight from the DB tier. */}
103	      <div key={sel} className="mt-3 motion-safe:animate-[var(--animate-price-pop)]">
104	        <div className="flex items-end justify-between gap-3">
105	          <div>
106	            <p className="text-[11px] uppercase tracking-wide text-slate-500">Starting at</p>
107	            <p className="text-3xl font-extrabold tracking-tight text-white">
108	              {money(tier.priceCents)}
109	              <span className="ml-1 text-sm font-normal text-slate-400">{per(tier.termMonths)}</span>
110	            </p>
111	          </div>
112	          {tier.slots != null && (
113	            <span className="pb-1 text-right text-xs text-slate-400">
114	              up to <span className="font-semibold text-white">{tier.slots}</span> slots
115	            </span>
116	          )}
117	        </div>
118	        <ul className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1.5 text-xs text-slate-300">
119	          <li className="flex items-center gap-1.5">
120	            <IconBolt size={13} className="text-brand-300" /> {gb(tier.ramMB)} RAM
121	          </li>
122	          <li className="flex items-center gap-1.5">
123	            <IconBolt size={13} className="text-brand-300" /> {tier.cpuCores} vCPU
124	          </li>
125	          <li className="flex items-center gap-1.5">
126	            <IconBolt size={13} className="text-brand-300" /> {tier.diskGB} GB NVMe
127	          </li>
128	          <li className="flex items-center gap-1.5">
129	            <IconBolt size={13} className="text-brand-300" /> DDoS protected
130	          </li>
131	        </ul>
132	      </div>
133	
134	      <Link href="#pricing" className="btn-primary mt-4 w-full text-center">
135	        See {game.name} plans
136	      </Link>
137	    </div>
138	  );
139	}
140	
141	export function GameShowcaseCarousel({ games }: { games: ShowcaseGame[] }) {
142	  const [active, setActive] = useState(0);
143	  const trackRef = useRef<HTMLDivElement>(null);
144	  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
145	
146	  if (games.length === 0) return null;
147	
148	  function select(i: number) {
149	    const idx = Math.max(0, Math.min(games.length - 1, i));
150	    setActive(idx);
151	    cardRefs.current[idx]?.scrollIntoView({
152	      behavior: "smooth",
153	      inline: "center",
154	      block: "nearest",
155	    });
156	  }
157	
158	  return (
159	    <div className="relative">
160	      {/* Arrow controls — hidden on touch-first small screens (swipe instead). */}
161	      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
162	        <button
163	          type="button"
164	          aria-label="Previous game"
165	          onClick={() => select(active - 1)}
166	          disabled={active === 0}
167	          className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white disabled:opacity-30 lg:-ml-5"
168	        >
169	          <span className="rotate-180">
170	            <IconArrow size={18} />
171	          </span>
172	        </button>
173	        <button
174	          type="button"
175	          aria-label="Next game"
176	          onClick={() => select(active + 1)}
177	          disabled={active === games.length - 1}
178	          className="pointer-events-auto -mr-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white disabled:opacity-30 lg:-mr-5"
179	        >
180	          <IconArrow size={18} />
181	        </button>
182	      </div>
183	
184	      {/* Scroll-snap track. Each cover is a fixed-width card; the active one grows
185	          and reveals the interactive selector. */}
186	      <div
187	        ref={trackRef}
188	        className="flex snap-x snap-mandatory gap-4 overflow-x-auto scroll-smooth pb-4 pt-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
189	      >
190	        {/* Edge spacers so the first/last card can center on scroll. */}
191	        <div aria-hidden className="w-2 shrink-0 sm:w-8" />
192	        {games.map((g, i) => {
193	          const visual = GAME_VISUAL[g.family] ?? { name: g.name, glyph: "🎮", ...NEUTRAL };
194	          const isActive = i === active;
195	          return (
196	            <div
197	              key={g.family}
198	              ref={(el) => {
199	                cardRefs.current[i] = el;
200	              }}
201	              className={`group relative flex shrink-0 snap-center flex-col overflow-hidden rounded-2xl border bg-navy-900/70 p-4 backdrop-blur-md transition-all duration-300 motion-safe:duration-300 ${
202	                isActive
203	                  ? "w-[19rem] border-white/15 sm:w-[21rem]"
204	                  : "w-[15rem] cursor-pointer border-white/[0.06] opacity-80 hover:opacity-100 sm:w-[16rem]"
205	              }`}
206	              style={
207	                isActive
208	                  ? { boxShadow: `0 0 60px -18px ${visual.to}, 0 8px 32px -12px rgb(0 0 0 / 0.5)` }
209	                  : undefined
210	              }
211	              onClick={() => !isActive && select(i)}
212	            >
213	              {/* Cover art — the brand gradient with the real logo mark. */}
214	              <div
215	                className="relative flex h-40 items-center justify-center overflow-hidden rounded-xl"
216	                style={{
217	                  background: `radial-gradient(120% 90% at 50% 0%, ${visual.from}, ${visual.to})`,
218	                }}
219	              >
220	                <div
221	                  aria-hidden
222	                  className="absolute inset-0 opacity-40 mix-blend-overlay"
223	                  style={{ background: "radial-gradient(80% 60% at 50% 120%, rgba(0,0,0,0.6), transparent)" }}
224	                />
225	                <GameLogo family={g.family} size={isActive ? 84 : 68} className="relative z-10 shadow-lg" />
226	                {g.tiers.some((t) => t.featured) && (
227	                  <span className="absolute right-2 top-2 z-10 rounded-full border border-white/25 bg-black/30 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
228	                    Popular
229	                  </span>
230	                )}
231	              </div>
232	
233	              {/* Title + tag */}
234	              <div className="mt-3 flex items-start justify-between gap-2">
235	                <div className="min-w-0">
236	                  <h3 className="truncate text-base font-bold text-white">{g.name}</h3>
237	                  <p className="truncate text-xs text-slate-400">{g.tag}</p>
238	                </div>
239	                {!isActive && (
240	                  <span className="shrink-0 text-right text-xs">
241	                    <span className="block text-slate-500">from</span>
242	                    <span className="font-semibold text-brand-300">{money(g.fromCents)}</span>
243	                  </span>
244	                )}
245	              </div>
246	
247	              {isActive ? (
248	                <ActivePanel game={g} />
249	              ) : (
250	                <p className="mt-2 text-xs text-slate-500">Tap to see specs & slots</p>
251	              )}
252	            </div>
253	          );
254	        })}
255	        <div aria-hidden className="w-2 shrink-0 sm:w-8" />
256	      </div>
257	
258	      {/* Dot indicators */}
259	      <div className="mt-2 flex items-center justify-center gap-2">
260	        {games.map((g, i) => (
261	          <button
262	            key={g.family}
263	            type="button"
264	            aria-label={`Show ${g.name}`}
265	            aria-current={i === active}
266	            onClick={() => select(i)}
267	            className={`h-1.5 rounded-full transition-all ${
268	              i === active ? "w-6 bg-brand-400" : "w-1.5 bg-white/20 hover:bg-white/40"
269	            }`}
270	          />
271	        ))}
272	      </div>
273	    </div>
274	  );
275	}
