1	"use client";
2	
3	/**
4	 * GameCoverCarousel — the hero cover carousel on /game-servers. A horizontal row
5	 * of portrait "box-art" cover cards; the centered card is enlarged with a brand
6	 * glow ring and shows an interactive player-slot selector, side cards are dimmed
7	 * and show their "Starting at $X/mo" anchor. ◀ ▶ arrows + dot indicators drive it;
8	 * on touch it is a scroll-snap swipe track.
9	 *
10	 * ── Cover art (owner drop-in, same convention as GameLogo) ───────────────────
11	 * Drop real key-art at:  public/logos/games/covers/<family>.{webp,jpg,png}
12	 * and it takes over the card with NO code change. Until then each card renders a
13	 * premium branded fallback (per-game gradient + the owner's wordmark logo + a
14	 * soft vignette) so the layout matches the design immediately.
15	 *
16	 * Every price / slot / spec below is read live from the DB game-plan tiers passed
17	 * in (ShowcaseGame) — no invented player counts or prices.
18	 */
19	
20	import { useRef, useState } from "react";
21	import Link from "next/link";
22	import { GameLogo, GAME_VISUAL } from "../GameLogo";
23	import { IconArrow, IconUsers, IconBolt } from "../icons";
24	import type { ShowcaseGame } from "./GameShowcaseCarousel";
25	
26	function money(cents: number) {
27	  const v = cents / 100;
28	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
29	}
30	function gb(mb: number) {
31	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
32	}
33	function per(term: number) {
34	  return term > 1 ? `/ ${term} mo` : "/mo";
35	}
36	
37	const NEUTRAL = { from: "#334155", to: "#64748b" };
38	
39	/** Portrait cover: owner drop-in key-art if present, else a branded wordmark poster. */
40	function GameCover({ family, name }: { family: string; name: string }) {
41	  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", ...NEUTRAL };
42	  // Resolution chain: real key-art (webp → jpg → png) first, then the owner's raw
43	  // wordmark rendered large on the game's gradient (poster-like, no tile), then a
44	  // plain gradient. All plain <img> so the onError chain can advance client-side.
45	  const chain = [
46	    `/logos/games/covers/${family}.webp`,
47	    `/logos/games/covers/${family}.jpg`,
48	    `/logos/games/covers/${family}.png`,
49	    `/logos/games/${family}.png`, // wordmark fallback
50	  ];
51	  const [idx, setIdx] = useState(0);
52	  const src = chain[idx];
53	  const exhausted = idx >= chain.length;
54	  const isWordmark = idx === chain.length - 1; // last candidate = wordmark, not full art
55	
56	  return (
57	    <div
58	      className="absolute inset-0"
59	      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
60	    >
61	      {isWordmark && (
62	        <div
63	          aria-hidden
64	          className="absolute inset-0 opacity-70 mix-blend-overlay"
65	          style={{ background: "radial-gradient(75% 55% at 50% 32%, rgba(255,255,255,0.28), transparent 72%)" }}
66	        />
67	      )}
68	      {!exhausted && (
69	        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
70	        <img
71	          key={src}
72	          src={src}
73	          alt={`${name} cover art`}
74	          onError={() => setIdx((i) => i + 1)}
75	          className={
76	            isWordmark
77	              ? "absolute left-1/2 top-[38%] w-[62%] max-w-[190px] -translate-x-1/2 -translate-y-1/2 object-contain drop-shadow-2xl"
78	              : "absolute inset-0 h-full w-full object-cover"
79	          }
80	        />
81	      )}
82	      {/* Readability scrim so the title/price overlay is always legible. */}
83	      <div
84	        aria-hidden
85	        className="absolute inset-x-0 bottom-0 h-2/3"
86	        style={{ background: "linear-gradient(to top, rgba(4,7,15,0.94), rgba(4,7,15,0.4) 52%, transparent)" }}
87	      />
88	    </div>
89	  );
90	}
91	
92	function SlotSelector({ game }: { game: ShowcaseGame }) {
93	  const slotted = game.tiers.filter((t) => t.slots != null);
94	  const options = slotted.length ? slotted : game.tiers;
95	  const defaultIdx = Math.max(0, options.findIndex((t) => t.featured));
96	  const [sel, setSel] = useState(defaultIdx === -1 ? 0 : defaultIdx);
97	  const tier = options[sel] ?? game.tiers[0];
98	  if (!tier) return null;
99	
100	  return (
101	    <div className="mt-3">
102	      {slotted.length > 0 && (
103	        <>
104	          <p className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300/80">
105	            <IconUsers size={12} /> Players
106	          </p>
107	          <div className="mt-1.5 flex flex-wrap gap-1.5" role="group" aria-label={`${game.name} player slots`}>
108	            {options.map((t, i) => (
109	              <button
110	                key={`${t.name}-${i}`}
111	                type="button"
112	                aria-pressed={i === sel}
113	                onClick={(e) => {
114	                  e.stopPropagation();
115	                  setSel(i);
116	                }}
117	                className={`rounded-md border px-2 py-0.5 text-xs font-semibold transition-colors ${
118	                  i === sel
119	                    ? "border-brand-400/70 bg-brand-500/25 text-white"
120	                    : "border-white/15 bg-black/30 text-slate-200 hover:border-white/30"
121	                }`}
122	              >
123	                {t.slots}
124	              </button>
125	            ))}
126	          </div>
127	        </>
128	      )}
129	      <div key={sel} className="mt-2.5 flex items-end justify-between gap-2 motion-safe:animate-[var(--animate-price-pop)]">
130	        <div>
131	          <p className="text-[10px] uppercase tracking-wide text-slate-400">Starting at</p>
132	          <p className="text-2xl font-extrabold tracking-tight text-white">
133	            {money(tier.priceCents)}
134	            <span className="ml-1 text-xs font-normal text-slate-300">{per(tier.termMonths)}</span>
135	          </p>
136	        </div>
137	        <span className="flex items-center gap-1 pb-1 text-[11px] text-slate-300">
138	          <IconBolt size={12} className="text-brand-300" /> {gb(tier.ramMB)} · {tier.cpuCores} vCPU
139	        </span>
140	      </div>
141	    </div>
142	  );
143	}
144	
145	export function GameCoverCarousel({ games }: { games: ShowcaseGame[] }) {
146	  const [active, setActive] = useState(Math.min(1, Math.max(0, games.length - 1)));
147	  const trackRef = useRef<HTMLDivElement>(null);
148	  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
149	
150	  if (games.length === 0) return null;
151	
152	  function select(i: number) {
153	    const idx = Math.max(0, Math.min(games.length - 1, i));
154	    setActive(idx);
155	    cardRefs.current[idx]?.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
156	  }
157	
158	  return (
159	    <div className="relative">
160	      {/* Arrow controls (pointer devices; swipe on touch). */}
161	      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-30 hidden items-center justify-between sm:flex">
162	        <button
163	          type="button"
164	          aria-label="Previous game"
165	          onClick={() => select(active - 1)}
166	          disabled={active === 0}
167	          className="pointer-events-auto -ml-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-ml-5"
168	        >
169	          <span className="rotate-180">
170	            <IconArrow size={18} />
171	          </span>
172	        </button>
173	        <button
174	          type="button"
175	          aria-label="Next game"
176	          onClick={() => select(active + 1)}
177	          disabled={active === games.length - 1}
178	          className="pointer-events-auto -mr-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-mr-5"
179	        >
180	          <IconArrow size={18} />
181	        </button>
182	      </div>
183	
184	      <div
185	        ref={trackRef}
186	        className="flex snap-x snap-mandatory items-center gap-4 overflow-x-auto scroll-smooth px-4 pb-4 pt-3 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
187	      >
188	        <div aria-hidden className="w-0 shrink-0 sm:w-6" />
189	        {games.map((g, i) => {
190	          const visual = GAME_VISUAL[g.family] ?? { name: g.name, glyph: "🎮", ...NEUTRAL };
191	          const isActive = i === active;
192	          return (
193	            <div
194	              key={g.family}
195	              ref={(el) => {
196	                cardRefs.current[i] = el;
197	              }}
198	              onClick={() => !isActive && select(i)}
199	              className={`group relative flex shrink-0 snap-center flex-col justify-end overflow-hidden rounded-2xl border transition-all duration-300 ${
200	                isActive
201	                  ? "z-20 h-[21rem] w-[14rem] border-brand-400/50 sm:h-[26rem] sm:w-[17rem]"
202	                  : "z-10 h-[17rem] w-[11rem] cursor-pointer border-white/10 opacity-70 hover:opacity-90 sm:h-[21rem] sm:w-[13rem]"
203	              }`}
204	              style={
205	                isActive
206	                  ? { boxShadow: `0 0 0 1px rgba(111,71,245,0.25), 0 0 70px -14px ${visual.to}, 0 20px 50px -20px rgba(0,0,0,0.7)` }
207	                  : { boxShadow: "0 12px 30px -18px rgba(0,0,0,0.7)" }
208	              }
209	            >
210	              <GameCover family={g.family} name={g.name} />
211	
212	              {g.tiers.some((t) => t.featured) && (
213	                <span className="absolute right-2.5 top-2.5 z-10 rounded-full border border-white/25 bg-black/45 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
214	                  Popular
215	                </span>
216	              )}
217	
218	              {/* Bottom overlay: title + tag, then live price/slots on the active card. */}
219	              <div className="relative z-10 p-4">
220	                <h3 className="text-base font-bold leading-tight text-white drop-shadow">{g.name}</h3>
221	                <p className="text-xs text-slate-300/90">{g.tag}</p>
222	                {isActive ? (
223	                  <SlotSelector game={g} />
224	                ) : (
225	                  <p className="mt-1.5 text-xs text-slate-200/90">
226	                    <span className="text-slate-400">from </span>
227	                    <span className="font-bold text-white">{money(g.fromCents)}</span>
228	                    <span className="text-slate-400"> /mo</span>
229	                  </p>
230	                )}
231	              </div>
232	            </div>
233	          );
234	        })}
235	        <div aria-hidden className="w-0 shrink-0 sm:w-6" />
236	      </div>
237	
