"use client";

/**
 * GameCoverCarousel — the premium hero cover carousel on /game-servers.
 *
 * A coverflow-style row of portrait "box-art" cover cards. The centered card is
 * enlarged with a brand glow ring and shows an interactive player-slot selector;
 * side cards recede (scale + dim + lift) so the focus reads instantly. Fully
 * hand-driven motion — NO native scroll-snap — so it feels high-end:
 *
 *   • Momentum drag / swipe: pointer + touch, with velocity-based flick that can
 *     skip multiple cards and always settles (snaps) on a card via a spring.
 *   • Trackpad / wheel: horizontal intent nudges the carousel (vertical page
 *     scroll is never hijacked).
 *   • ◀ ▶ arrows, ← → / Home / End keyboard, and clickable dot indicators.
 *   • Autoplay that pauses on hover, focus, drag, tab-hidden, or reduced-motion.
 *   • Continuous depth: every card's scale/opacity/offset is recomputed each
 *     frame from the live fractional position, so scaling tracks the drag fluidly.
 *   • prefers-reduced-motion: autoplay off, transitions become instant snaps.
 *
 * ── Cover art (owner drop-in) ────────────────────────────────────────────────
 * Resolution chain, first that loads wins (all plain <img> so onError advances
 * client-side):
 *   1. /games/art/<artSlug>_poster.jpg   ← real portrait key-art (ships today)
 *   2. /logos/games/covers/<family>.{webp,jpg,png}   ← owner cover drop-in
 *   3. /logos/games/<family>.png         ← owner wordmark on the brand gradient
 *   4. per-game gradient + emoji glyph    ← never blank
 *
 * Every price / slot / spec is read live from the DB game-plan tiers passed in
 * (ShowcaseGame) — no invented player counts or prices.
 */

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import Link from "next/link";
import { GameLogo, GAME_VISUAL } from "../GameLogo";
import { IconArrow, IconUsers, IconBolt } from "../icons";
import type { ShowcaseGame } from "./GameShowcaseCarousel";

/* ── formatting helpers (DB figures in, display strings out) ─────────────────── */
function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}
function gb(mb: number) {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}
function per(term: number) {
  return term > 1 ? `/ ${term} mo` : "/mo";
}

const NEUTRAL = { from: "#334155", to: "#64748b" };

/**
 * Family id → art slug for the rich portrait posters bundled at
 * public/games/art/<slug>_poster.jpg (naming differs from the family id for a
 * few titles). Missing entries fall straight through to the cover / wordmark
 * chain, so this is purely additive.
 */
const ART_SLUG: Record<string, string> = {
  projectzomboid: "project-zomboid",
  sdtd: "7-days-to-die",
  theforest: "the-forest",
  sonsoftheforest: "sons-of-the-forest",
  conan: "conan-exiles",
  ark: "ark-asa",
  vrising: "vrising",
  cs2: "cs2",
  rust: "rust",
  palworld: "palworld",
  valheim: "valheim",
  terraria: "terraria",
  enshrouded: "enshrouded",
  factorio: "factorio",
  gmod: "gmod",
  unturned: "unturned",
  dayz: "dayz",
  satisfactory: "satisfactory",
};

/* ── responsive geometry (must match the card markup below) ──────────────────── */
const MOMENTUM = 0.9; // how far a flick's velocity carries (in card-units)
const MAX_FLICK = 3; // cap cards skipped by a single flick

/** Portrait cover: real poster art if present, else cover drop-in, else wordmark. */
function GamePoster({ family, name }: { family: string; name: string }) {
  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", ...NEUTRAL };
  const slug = ART_SLUG[family];
  const chain = [
    slug ? `/games/art/${slug}_poster.jpg` : "",
    `/logos/games/covers/${family}.webp`,
    `/logos/games/covers/${family}.jpg`,
    `/logos/games/covers/${family}.png`,
    `/logos/games/${family}.png`, // wordmark fallback
  ].filter(Boolean) as string[];

  const [idx, setIdx] = useState(0);
  const src = chain[idx];
  const exhausted = idx >= chain.length;
  const isWordmark = !exhausted && idx === chain.length - 1;

  return (
    <div
      className="absolute inset-0"
      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
    >
      {(isWordmark || exhausted) && (
        <div
          aria-hidden
          className="absolute inset-0 opacity-70 mix-blend-overlay"
          style={{ background: "radial-gradient(75% 55% at 50% 32%, rgba(255,255,255,0.28), transparent 72%)" }}
        />
      )}
      {exhausted ? (
        <div className="absolute left-1/2 top-[36%] -translate-x-1/2 -translate-y-1/2">
          <GameLogo family={family} size={88} />
        </div>
      ) : (
        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
        <img
          key={src}
          src={src}
          alt={`${name} cover art`}
          draggable={false}
          onError={() => setIdx((i) => i + 1)}
          className={
            isWordmark
              ? "absolute left-1/2 top-[38%] w-[62%] max-w-[190px] -translate-x-1/2 -translate-y-1/2 select-none object-contain drop-shadow-2xl"
              : "absolute inset-0 h-full w-full select-none object-cover"
          }
        />
      )}
      {/* Readability scrim so the title/price overlay is always legible. */}
      <div
        aria-hidden
        className="absolute inset-x-0 bottom-0 h-3/4"
        style={{ background: "linear-gradient(to top, rgba(4,7,15,0.96), rgba(4,7,15,0.45) 48%, transparent)" }}
      />
    </div>
  );
}

/** Interactive player-slot selector for the active card (all figures DB-fed). */
function SlotSelector({ game }: { game: ShowcaseGame }) {
  const slotted = game.tiers.filter((t) => t.slots != null);
  const options = slotted.length ? slotted : game.tiers;
  const defaultIdx = Math.max(0, options.findIndex((t) => t.featured));
  const [sel, setSel] = useState(defaultIdx === -1 ? 0 : defaultIdx);
  const tier = options[sel] ?? game.tiers[0];
  if (!tier) return null;

  return (
    <div className="mt-3">
      {slotted.length > 0 && (
        <>
          <p className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300/80">
            <IconUsers size={12} /> Players
          </p>
          <div className="mt-1.5 flex flex-wrap gap-1.5" role="group" aria-label={`${game.name} player slots`}>
            {options.map((t, i) => (
              <button
                key={`${t.name}-${i}`}
                type="button"
                aria-pressed={i === sel}
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  setSel(i);
                }}
                className={`rounded-md border px-2 py-0.5 text-xs font-semibold transition-colors ${
                  i === sel
                    ? "border-brand-400/70 bg-brand-500/25 text-white"
                    : "border-white/15 bg-black/30 text-slate-200 hover:border-white/30"
                }`}
              >
                {t.slots}
              </button>
            ))}
          </div>
        </>
      )}
      <div
        key={sel}
        className="mt-2.5 flex items-end justify-between gap-2 motion-safe:animate-[var(--animate-price-pop)]"
      >
        <div>
          <p className="text-[10px] uppercase tracking-wide text-slate-400">Starting at</p>
          <p className="text-2xl font-extrabold tracking-tight text-white">
            {money(tier.priceCents)}
            <span className="ml-1 text-xs font-normal text-slate-300">{per(tier.termMonths)}</span>
          </p>
        </div>
        <span className="flex items-center gap-1 pb-1 text-[11px] text-slate-300">
          <IconBolt size={12} className="text-brand-300" /> {gb(tier.ramMB)} · {tier.cpuCores} vCPU
        </span>
      </div>
    </div>
  );
}

/** SSR-safe layout effect (avoids the React useLayoutEffect-on-server warning). */
const useIsoLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

export function GameCoverCarousel({ games }: { games: ShowcaseGame[] }) {
  const n = games.length;
  // Start on the first "Popular" title, else the second card for a coverflow feel.
  const initial = (() => {
    const f = games.findIndex((g) => g.tiers.some((t) => t.featured));
    return f >= 0 ? f : Math.min(1, Math.max(0, n - 1));
  })();

  const [active, setActive] = useState(initial);
  const [ready, setReady] = useState(false);
  const [paused, setPaused] = useState(false);

  const viewportRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  const offsetRef = useRef(initial); // live fractional position (in card-units)
  const targetRef = useRef(initial);
  const rafRef = useRef<number | null>(null);
  const reducedRef = useRef(false);
  const activeRef = useRef(initial); // mirror for handlers without re-subscribing

  const clamp = useCallback((i: number) => Math.max(0, Math.min(n - 1, i)), [n]);

  /* Paint one frame: track translate + per-card depth, from offsetRef. */
  const paint = useCallback(() => {
    const vp = viewportRef.current;
    const track = trackRef.current;
    const first = cardRefs.current[0];
    const second = cardRefs.current[1];
    if (!vp || !track || !first) return;

    const cardW = first.offsetWidth;
    const step = second ? second.offsetLeft - first.offsetLeft : cardW;
    const base = first.offsetLeft + cardW / 2; // center of card 0 within the track
    const vpCenter = vp.clientWidth / 2;
    const off = offsetRef.current;

    track.style.transform = `translate3d(${vpCenter - base - off * step}px,0,0)`;

    const cards = cardRefs.current;
    for (let i = 0; i < cards.length; i++) {
      const el = cards[i];
      if (!el) continue;
      const d = i - off; // signed distance from center, in cards
      const a = Math.min(Math.abs(d), 1.6);
      const scale = 1.08 - a * 0.19; // center pops, neighbours recede
      const lift = a * 14; // side cards drop slightly
      const rot = Math.max(-1, Math.min(1, d)) * -5; // faint coverflow tilt
      const opacity = 1 - Math.min(a, 1) * 0.5;
      el.style.transform = `translateY(${lift}px) scale(${scale}) perspective(1000px) rotateY(${rot}deg)`;
      el.style.opacity = `${opacity}`;
      el.style.zIndex = `${100 - Math.round(a * 10)}`;
    }
  }, []);

  /* Spring toward targetRef; commit `active` when it settles. */
  const animate = useCallback(() => {
    const diff = targetRef.current - offsetRef.current;
    if (Math.abs(diff) < 0.0015) {
      offsetRef.current = targetRef.current;
      paint();
      rafRef.current = null;
      const idx = clamp(Math.round(offsetRef.current));
      activeRef.current = idx;
      setActive(idx);
      return;
    }
    offsetRef.current += diff * 0.185;
    paint();
    rafRef.current = requestAnimationFrame(animate);
  }, [paint, clamp]);

  /* Settle onto a target card (instant when reduced-motion). */
  const settleTo = useCallback(
    (target: number) => {
      targetRef.current = clamp(target);
      if (reducedRef.current) {
        offsetRef.current = targetRef.current;
        paint();
        const idx = clamp(Math.round(targetRef.current));
        activeRef.current = idx;
        setActive(idx);
        return;
      }
      if (rafRef.current == null) rafRef.current = requestAnimationFrame(animate);
    },
    [animate, paint, clamp],
  );

  const go = useCallback((i: number) => settleTo(i), [settleTo]);

  /* ── mount: detect reduced-motion, first layout, resize + fade-in ──────────── */
  useIsoLayoutEffect(() => {
    reducedRef.current =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    paint();
    setReady(true);
    const onResize = () => paint();
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("resize", onResize);
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
    // paint is stable; run once on mount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ── pointer / touch momentum drag ─────────────────────────────────────────── */
  useEffect(() => {
    const vp = viewportRef.current;
    const track = trackRef.current;
    const first = cardRefs.current[0];
    const second = cardRefs.current[1];
    if (!vp || !track) return;

    let dragging = false;
    let moved = false;
    let startX = 0;
    let startOffset = 0;
    let lastX = 0;
    let lastT = 0;
    let velocity = 0; // card-units per ms
    let step = second && first ? second.offsetLeft - first.offsetLeft : first?.offsetWidth || 1;

    const onDown = (e: PointerEvent) => {
      if (e.button != null && e.button !== 0) return;
      const f = cardRefs.current[0];
      const s = cardRefs.current[1];
      step = s && f ? s.offsetLeft - f.offsetLeft : f?.offsetWidth || step;
      dragging = true;
      moved = false;
      startX = lastX = e.clientX;
      startOffset = offsetRef.current;
      lastT = e.timeStamp;
      velocity = 0;
      if (rafRef.current != null) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }
      setPaused(true);
      track.style.transition = "none";
      vp.setPointerCapture?.(e.pointerId);
    };

    const onMove = (e: PointerEvent) => {
      if (!dragging) return;
      const dx = e.clientX - startX;
      if (Math.abs(dx) > 4) moved = true;
      offsetRef.current = clamp(startOffset - dx / step);
      const dt = e.timeStamp - lastT || 16;
      velocity = -(e.clientX - lastX) / step / dt;
      lastX = e.clientX;
      lastT = e.timeStamp;
      paint();
    };

    const onUp = (e: PointerEvent) => {
      if (!dragging) return;
      dragging = false;
      vp.releasePointerCapture?.(e.pointerId);
      // Fold flick velocity into how many cards we travel, then snap.
      const flick = Math.max(-MAX_FLICK, Math.min(MAX_FLICK, velocity * 1000 * MOMENTUM));
      const target = clamp(Math.round(offsetRef.current + flick));
      settleTo(target);
      // Suppress the click that follows a real drag.
      if (moved) {
        const stop = (ev: Event) => {
          ev.stopPropagation();
          ev.preventDefault();
        };
        vp.addEventListener("click", stop, { capture: true, once: true });
      }
    };

    vp.addEventListener("pointerdown", onDown);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      vp.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [clamp, paint, settleTo]);

  /* ── trackpad / wheel (horizontal intent only) ─────────────────────────────── */
  useEffect(() => {
    const vp = viewportRef.current;
    if (!vp) return;
    let lock = 0;
    const onWheel = (e: WheelEvent) => {
      const horizontal = Math.abs(e.deltaX) > Math.abs(e.deltaY);
      if (!horizontal) return; // never hijack vertical page scroll
      e.preventDefault();
      const now = e.timeStamp;
      if (now - lock < 260) return;
      lock = now;
      settleTo(clamp(Math.round(targetRef.current) + (e.deltaX > 0 ? 1 : -1)));
    };
    vp.addEventListener("wheel", onWheel, { passive: false });
    return () => vp.removeEventListener("wheel", onWheel);
  }, [clamp, settleTo]);

  /* ── autoplay (pauses on hover/focus/drag/hidden/reduced-motion) ───────────── */
  useEffect(() => {
    if (paused || reducedRef.current || n <= 1) return;
    const id = window.setInterval(() => {
      if (document.hidden) return;
      const next = activeRef.current + 1 >= n ? 0 : activeRef.current + 1;
      settleTo(next);
    }, 4200);
    return () => window.clearInterval(id);
  }, [paused, n, settleTo]);

  if (n === 0) return null;

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      go(activeRef.current - 1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      go(activeRef.current + 1);
    } else if (e.key === "Home") {
      e.preventDefault();
      go(0);
    } else if (e.key === "End") {
      e.preventDefault();
      go(n - 1);
    }
  };

  return (
    <div
      className="relative"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocusCapture={() => setPaused(true)}
      onBlurCapture={() => setPaused(false)}
    >
      {/* Arrow controls (pointer devices; swipe on touch). */}
      <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-40 hidden items-center justify-between sm:flex">
        <button
          type="button"
          aria-label="Previous game"
          onClick={() => go(active - 1)}
          disabled={active === 0}
          className="pointer-events-auto -ml-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-ml-5"
        >
          <span className="rotate-180">
            <IconArrow size={18} />
          </span>
        </button>
        <button
          type="button"
          aria-label="Next game"
          onClick={() => go(active + 1)}
          disabled={active === n - 1}
          className="pointer-events-auto -mr-3 grid h-11 w-11 place-items-center rounded-full border border-white/10 bg-navy-950/80 text-slate-200 backdrop-blur transition hover:border-brand-500/50 hover:text-white disabled:opacity-25 lg:-mr-5"
        >
          <IconArrow size={18} />
        </button>
      </div>

      {/* Viewport — clips horizontally, pads vertically so the active glow fits. */}
      <div
        ref={viewportRef}
        role="group"
        aria-roledescription="carousel"
        aria-label="Featured game servers"
        tabIndex={0}
        onKeyDown={onKeyDown}
        className="relative overflow-hidden px-2 py-6 outline-none [touch-action:pan-y] focus-visible:ring-2 focus-visible:ring-brand-500/40"
        style={{ cursor: "grab" }}
      >
        <div
          ref={trackRef}
          className="flex w-max items-center gap-4 will-change-transform"
          style={{ opacity: ready ? 1 : 0, transition: "opacity .4s ease" }}
        >
          {games.map((g, i) => {
            const visual = GAME_VISUAL[g.family] ?? { name: g.name, glyph: "🎮", ...NEUTRAL };
            const isActive = i === active;
            return (
              <div
                key={g.family}
                ref={(el) => {
                  cardRefs.current[i] = el;
                }}
                role="group"
                aria-roledescription="slide"
                aria-label={`${g.name} — slide ${i + 1} of ${n}`}
                aria-hidden={!isActive}
                onClick={() => !isActive && go(i)}
                className={`group relative flex h-[22rem] w-[13rem] shrink-0 select-none flex-col justify-end overflow-hidden rounded-2xl border sm:h-[26rem] sm:w-[16rem] ${
                  isActive
                    ? "border-brand-400/50"
                    : "cursor-pointer border-white/10 hover:border-white/20"
                }`}
                style={{
                  boxShadow: isActive
                    ? `0 0 0 1px rgba(111,71,245,0.25), 0 0 80px -14px ${visual.to}, 0 24px 60px -22px rgba(0,0,0,0.75)`
                    : "0 14px 34px -20px rgba(0,0,0,0.75)",
                }}
              >
                <GamePoster family={g.family} name={g.name} />

                {g.tiers.some((t) => t.featured) && (
                  <span className="absolute right-2.5 top-2.5 z-10 rounded-full border border-white/25 bg-black/45 px-2 py-0.5 text-[10px] font-semibold text-white backdrop-blur">
                    Popular
                  </span>
                )}

                {/* Bottom overlay: title + tag, then live price/slots on the active card. */}
                <div className="relative z-10 p-4">
                  <h3 className="text-base font-bold leading-tight text-white drop-shadow">{g.name}</h3>
                  <p className="text-xs text-slate-300/90">{g.tag}</p>
                  {isActive ? (
                    <SlotSelector game={g} />
                  ) : (
                    <p className="mt-1.5 text-xs text-slate-200/90">
                      <span className="text-slate-400">from </span>
                      <span className="font-bold text-white">{money(g.fromCents)}</span>
                      <span className="text-slate-400"> /mo</span>
                    </p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Live region so screen readers hear the centered title change. */}
      <p className="sr-only" aria-live="polite">
        {games[active]?.name} selected, from {money(games[active]?.fromCents ?? 0)} per month
      </p>

      {/* Dot indicators */}
      <div className="mt-1 flex flex-wrap items-center justify-center gap-2">
        {games.map((g, i) => (
          <button
            key={g.family}
            type="button"
            aria-label={`Show ${g.name}`}
            aria-current={i === active}
            onClick={() => go(i)}
            className={`h-1.5 rounded-full transition-all ${
              i === active ? "w-6 bg-brand-400" : "w-1.5 bg-white/25 hover:bg-white/45"
            }`}
          />
        ))}
      </div>

      {/* CTA under the carousel — jumps to the live configurator for the active title. */}
      <div className="mt-4 flex justify-center">
        <Link href="#configure" className="btn-primary">
          See {games[active]?.name} plans →
        </Link>
      </div>
    </div>
  );
}
